/* From Uiverse.io by Christardev - Tags: button, form, input, animated, border, card template */
.__UIV_SCOPE__ .password {
  outline: none;
  max-width: 190px;
  padding: 8px;
  background-color: #d4cbcb;
  border-radius: 12px;
  border: 4px solid #000000;
  width: auto;
  font-weight: bold;
  font-style: italic;
}

.__UIV_SCOPE__ .password:hover {
  background-color: #6ad5f0;
  outline: none;
  border: 4px solid #000000;
}
